357→// FetchMetadataBranch fetches the entire/checkpoints/v1 branch from origin and creates/updates the local branch.
358→// This is used when the metadata branch exists on remote but not locally.
359→// Uses git CLI instead of go-git for fetch because go-git doesn't use credential helpers,
360→// which breaks HTTPS URLs that require authentication.
361→func FetchMetadataBranch(ctx context.Context) error {
362→	branchName := paths.MetadataBranchName
363→
364→	// Use git CLI for fetch (go-git's fetch can be tricky with auth)
365→	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
366→	defer cancel()
367→
368→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
369→
370→	fetchCmd := exec.CommandContext(ctx, "git", "fetch", "origin", refSpec)
371→	if output, err := fetchCmd.CombinedOutput(); err != nil {
372→		if ctx.Err() == context.DeadlineExceeded {
373→			return errors.New("fetch timed out after 2 minutes")
374→		}
375→		return fmt.Errorf("failed to fetch %s from origin: %s: %w", branchName, strings.TrimSpace(string(output)), err)
376→	}
377→
378→	repo, err := openRepository(ctx)
379→	if err != nil {
380→		return fmt.Errorf("failed to open repository: %w", err)
381→	}
382→
383→	// Get the remote branch reference
384→	remoteRef, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
385→	if err != nil {
386→		return fmt.Errorf("branch '%s' not found on origin: %w", branchName, err)
387→	}
388→
389→	// Create or update local branch pointing to the same commit
390→	localRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
391→	if err := repo.Storer.SetReference(localRef); err != nil {
392→		return fmt.Errorf("failed to create local %s branch: %w", branchName, err)
393→	}
394→
395→	return nil
396→}
