601→// RestoreLogsOnly restores session logs from a logs-only rewind point.
602→// This fetches the transcript from entire/checkpoints/v1 and writes it to the agent's session directory.
603→// Does not modify the working directory.
604→// When multiple sessions were condensed to the same checkpoint, ALL sessions are restored.
605→// If force is false, prompts for confirmation when local logs have newer timestamps.
606→// Returns info about each restored session so callers can print correct per-session resume commands.
607→func (s *ManualCommitStrategy) RestoreLogsOnly(ctx context.Context, point RewindPoint, force bool) ([]RestoredSession, error) {
608→	if !point.IsLogsOnly {
609→		return nil, errors.New("not a logs-only rewind point")
610→	}
611→
612→	if point.CheckpointID.IsEmpty() {
613→		return nil, errors.New("missing checkpoint ID")
614→	}
615→
616→	// Get checkpoint store
617→	store, err := s.getCheckpointStore()
618→	if err != nil {
619→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
620→	}
621→
622→	// Read checkpoint summary to get session count
623→	summary, err := store.ReadCommitted(ctx, point.CheckpointID)
624→	if err != nil {
625→		return nil, fmt.Errorf("failed to read checkpoint: %w", err)
626→	}
627→	if summary == nil {
628→		return nil, fmt.Errorf("checkpoint not found: %s", point.CheckpointID)
629→	}
630→
631→	// Get worktree root for agent session directory lookup
632→	repoRoot, err := paths.WorktreeRoot(ctx)
633→	if err != nil {
634→		return nil, fmt.Errorf("failed to get worktree root: %w", err)
635→	}
636→
637→	// Check for newer local logs if not forcing
638→	if !force {
639→		sessions := s.classifySessionsForRestore(ctx, repoRoot, store, point.CheckpointID, summary)
640→		hasConflicts := false
641→		for _, sess := range sessions {
642→			if sess.Status == StatusLocalNewer {
643→				hasConflicts = true
644→				break
645→			}
646→		}
647→		if hasConflicts {
648→			shouldOverwrite, promptErr := PromptOverwriteNewerLogs(sessions)
649→			if promptErr != nil {
650→				return nil, promptErr
651→			}
652→			if !shouldOverwrite {
653→				fmt.Fprintf(os.Stderr, "Resume cancelled. Local session logs preserved.\n")
654→				return nil, nil
655→			}
656→		}
657→	}
658→
659→	// Count sessions to restore
660→	totalSessions := len(summary.Sessions)
661→	if totalSessions > 1 {
662→		fmt.Fprintf(os.Stderr, "Restoring %d sessions from checkpoint:\n", totalSessions)
663→	}
664→
665→	// Restore all sessions (oldest to newest, using 0-based indexing)
666→	var restored []RestoredSession
667→	for i := range totalSessions {
668→		content, readErr := store.ReadSessionContent(ctx, point.CheckpointID, i)
669→		if readErr != nil {
670→			fmt.Fprintf(os.Stderr, "  Warning: failed to read session %d: %v\n", i, readErr)
671→			continue
672→		}
673→		if content == nil || len(content.Transcript) == 0 {
674→			continue
675→		}
676→
677→		sessionID := content.Metadata.SessionID
678→		if sessionID == "" {
679→			fmt.Fprintf(os.Stderr, "  Warning: session %d has no session ID, skipping\n", i)
680→			continue
681→		}
682→
683→		// Resolve per-session agent from metadata — skip if agent is unknown
684→		if content.Metadata.Agent == "" {
685→			fmt.Fprintf(os.Stderr, "  Warning: session %d (%s) has no agent metadata, skipping (cannot determine target directory)\n", i, sessionID)
686→			continue
687→		}
688→		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
689→		if agErr != nil {
690→			fmt.Fprintf(os.Stderr, "  Warning: session %d (%s) has unknown agent %q, skipping\n", i, sessionID, content.Metadata.Agent)
691→			continue
692→		}
693→
694→		// Compute transcript path from current repo location for cross-machine portability.
695→		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
696→		if dirErr != nil {
697→			fmt.Fprintf(os.Stderr, "  Warning: failed to get session dir for session %d: %v\n", i, dirErr)
698→			continue
699→		}
700→		sessionFile := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
701→
702→		// Get first prompt for display
703→		promptPreview := ExtractFirstPrompt(content.Prompts)
704→
705→		if totalSessions > 1 {
706→			isLatest := i == totalSessions-1
707→			if promptPreview != "" {
708→				if isLatest {
709→					fmt.Fprintf(os.Stderr, "  Session %d (latest): %s\n", i+1, promptPreview)
710→				} else {
711→					fmt.Fprintf(os.Stderr, "  Session %d: %s\n", i+1, promptPreview)
712→				}
713→			}
714→			fmt.Fprintf(os.Stderr, "    Writing to: %s\n", sessionFile)
715→		} else {
716→			fmt.Fprintf(os.Stderr, "Writing transcript to: %s\n", sessionFile)
717→		}
718→
719→		// Ensure parent directory exists (session file may be in a different dir than sessionAgentDir)
720→		if mkdirErr := os.MkdirAll(filepath.Dir(sessionFile), 0o750); mkdirErr != nil {
721→			fmt.Fprintf(os.Stderr, "    Warning: failed to create directory: %v\n", mkdirErr)
722→			continue
723→		}
724→
725→		agentSession := &agent.AgentSession{
726→			SessionID:  sessionID,
727→			AgentName:  sessionAgent.Name(),
728→			RepoPath:   repoRoot,
729→			SessionRef: sessionFile,
730→			NativeData: content.Transcript,
731→		}
732→		if writeErr := sessionAgent.WriteSession(ctx, agentSession); writeErr != nil {
733→			if totalSessions > 1 {
734→				fmt.Fprintf(os.Stderr, "    Warning: failed to write session: %v\n", writeErr)
735→				continue
736→			}
737→			return nil, fmt.Errorf("failed to write session: %w", writeErr)
738→		}
739→
740→		restored = append(restored, RestoredSession{
741→			SessionID: sessionID,
742→			Agent:     sessionAgent.Type(),
743→			Prompt:    promptPreview,
744→			CreatedAt: content.Metadata.CreatedAt,
745→		})
746→	}
747→
748→	return restored, nil
749→}
