    // Then update local branch ref (same pattern as FetchMetadataBranch)
}

// FetchBlobsByHash fetches specific blob objects from the remote by hash.
// Uses git fetch-pack with individual object hashes.
// Falls back to full metadata branch fetch if fetch-pack fails.
func FetchBlobsByHash(ctx context.Context, hashes []plumbing.Hash) error {
    // Get remote URL
    // git fetch-pack --thin --no-progress <url> <hash1> <hash2> ...
    // Fallback: git fetch origin +refs/heads/entire/checkpoints/v1:...
}
```

#### 4. `resume.go` — Updated flow

```go
func getMetadataTree(ctx context.Context, repo *git.Repository) (*object.Tree, error) {
    // 1. Try local branch
    // 2. Treeless fetch via FetchMetadataTreeOnly()
    // 3. Fallback: full fetch via FetchMetadataBranch()
}

// ensureTranscriptBlobs checks which transcript blobs are local and
// fetches any missing ones from the remote.
func ensureTranscriptBlobs(ctx context.Context, repo *git.Repository, cpID id.CheckpointID) error {
    store := checkpoint.NewGitStore(repo)
    refs, _ := store.CollectTranscriptBlobHashes(ctx, cpID)

    resolver := checkpoint.NewBlobResolver(repo.Storer)
    var missing []plumbing.Hash
    for _, ref := range refs {
        if !resolver.HasBlob(ref.BlobHash) {
            missing = append(missing, ref.BlobHash)
        }
    }
    if len(missing) == 0 {
        return nil // all blobs already local
    }
    return FetchBlobsByHash(ctx, missing)
}
```

### Test Plan

All tests use local bare repos as remotes — no network, no auth.

