func TestCollectTranscriptBlobHashes_SingleSession(t *testing.T) {
	t.Parallel()

	_, store, cpID := setupRepoForUpdate(t)

	tree, err := store.getSessionsBranchTree()
	if err != nil {
		t.Fatalf("getSessionsBranchTree() error = %v", err)
